INSERT INTO `script_library` (`scene_id`, `title`, `parent_expression`, `reply_template`, `strategy`, `risk`, `sort_order`) VALUES
('child-bullied', '孩子被欺负', '老师，我家孩子在学校被同学打了，你们到底怎么管的？', '{家长称呼}您好，听到{学生姓名}的遭遇我也很揪心，孩子在学校的安全是我们最看重的。第一时间我已向涉事同学了解情况，并联系了对方家长共同处理。建议您先安抚{学生姓名}的情绪，我也会持续关注{具体行为}这类情况的改善，必要时咱们一起到校面谈，共同帮孩子建立安全感。', '先共情家长焦虑，客观还原事实避免站队；同步已采取的处置与后续跟进，给家长可控的预期。', '未经核实不要直接认定责任方；避免使用"打""欺负"等定性词，改用"发生了肢体冲突"等中性表述；不承诺赔偿或处罚具体结果。', 1),
('too-much-homework', '作业太多', '每天作业写到十一二点，孩子都累坏了，这作业是不是太多了？', '{家长称呼}您好，非常理解您的心疼，作业量过大确实会影响{学生姓名}的休息和兴趣发展。我已经和{班级名称}各科老师协调，对作业总量做了统筹与精简。建议您帮{学生姓名}记录连续几天的实际用时反馈给我，咱们一起判断是总量问题还是{具体行为}（如时间管理）问题，再针对性调整。', '承认家长关切合理性，给出可量化的反馈收集方式，避免笼统承诺"减作业"。', '不要直接否定作业安排或归咎某科老师；避免承诺立即大幅削减，以免与教学进度冲突引发其他家长不满。', 2),
('teacher-favoritism', '老师偏心', '老师是不是偏心啊，我家孩子总坐后排，机会都给别人了。', '{家长称呼}您好，感谢您愿意跟我坦诚交流。座位与机会的安排我都会综合考虑身高、视力、轮换规则等因素，绝不是区别对待{学生姓名}。我可以把{班级名称}近期的座位轮换表和课堂发言记录发您看一下，如果您有具体顾虑（如视力、听力）也请告诉我，我会在合理范围内优先调整。', '用客观规则和数据回应"偏心"质疑，将主观情绪转化为可讨论的具体因素。', '不要急于辩解或情绪化反驳；不要透露其他学生的具体信息；避免承诺"特殊照顾"引发新的公平争议。', 3),
('grade-decline', '成绩下滑', '这次考试孩子成绩掉了一大截，是不是上课没认真听？', '{家长称呼}您好，关心则乱，您的心情我特别能理解。{学生姓名}这次成绩确实有波动，我和各科老师分析后认为主要原因是{具体行为}（如某个知识点没掌握/近期状态调整）。建议咱们先不给孩子贴标签，而是陪{学生姓名}一起复盘错题，把薄弱环节补上。我也会在课堂上多关注、多提问，必要时安排同伴互助。', '把"成绩下滑"转化为"阶段性波动"，给出可操作的复盘路径，避免归因到孩子个人或老师。', '不要在群里或公开场合点名排名；避免直接归因"上课不听讲"伤害孩子自尊；不承诺提分幅度。', 4),
('seat-vision', '座位问题', '我家孩子近视，怎么给调到后排/边上了？', '{家长称呼}您好，孩子视力的事我记下了，这确实是要优先照顾的。{班级名称}的座位每两周轮换一次，{学生姓名}目前的座位属于正常轮换周期。如果您方便，可以把近期的视力检查单发我，我会在下一轮或近期就把{学生姓名}调到更合适的位置，同时留意黑板反光角度。', '承认合理诉求，以客观凭证（视力单）为调整依据，避免凭家长一句话就调座引发连锁要求。', '不要在群里公开讨论座位调整细节；避免"谁闹给谁调"的先例；调整后跟进确认效果。', 5),
('improper-criticism', '批评不当', '听说老师当着全班面批评我家孩子，孩子回家哭半天。', '{家长称呼}您好，听到{学生姓名}回家哭了我心里也很过意不去，孩子的自尊心咱们要一起呵护。当时的情况是{具体行为}，我的本意是提醒而非否定孩子，可能表达方式没照顾到{学生姓名}的感受，这一点我会反思。建议您先安抚孩子，告诉Ta老师是关心Ta才提醒，我也找机会单独和{学生姓名}聊一聊，把这件事翻篇。', '不回避家长对"当众批评"的指控，先共情孩子感受，适度反思表达方式，但坚守教育管理底线。', '不要全盘认错或道歉过度以免被截图放大；不要把责任推给孩子"玻璃心"；不承诺"以后绝不批评"。', 6),
('class-management-dispute', '班级管理争议', '班级纪律太差了，我家孩子回家说上课乱哄哄的，老师管不住？', '{家长称呼}您好，感谢您把{学生姓名}反馈的情况告诉我，班级氛围确实需要家校共同维护。客观说{班级名称}整体纪律在进步，但个别时段（如课间衔接、副科）确实还有提升空间。我已经加强了课堂常规巡查，也正引导孩子们建立自主管理的小组机制。如果{学生姓名}遇到具体干扰，欢迎随时告诉我，我会针对性处理。', '承认改进空间但不坐实"管不住"标签，用具体措施和机制回应，避免与家长对立。', '不要点名批评个别"调皮"学生；不要把纪律问题归因到某一科老师；措辞避免被解读为管理失职。', 7),
('seat-adjustment-request', '调座位诉求', '能不能把我家孩子调到前面/跟某某同桌？', '{家长称呼}您好，理解您想给{学生姓名}一个更好学习环境的用心。座位安排我会综合考虑视力身高、学习搭配、性格互补等因素，尽量让每个孩子都有合适的位置。您方便的话告诉我具体顾虑（如视力、专注力），我在符合{班级名称}轮换规则的前提下优先调整。也请您理解，每调一桌都会牵动周围，我会平衡好整体。', '把单一家长诉求放入"公平+规则"框架，让调整有依据、可解释，避免开"后门"先例。', '不要承诺"马上调"或"一定调到某位";避免因个别家长诉求反复打乱全班座位;不在群里公开协商座位。', 8),
('homework-ungraded', '作业没批改', '孩子的作业本好几天没批改了，老师是不是太忙顾不上？', '{家长称呼}您好，感谢您的提醒，作业批改反馈确实很重要。{学生姓名}的作业我会逐一核查，可能近期{具体行为}（如集中测验批阅/新课推进）导致个别批次反馈滞后，这不是不重视。我会在本周内补齐批改并标注问题，后续也会更及时地把错题反馈给{学生姓名}和您。', '不否认家长发现的问题，给出可核查的补救时间和后续承诺，避免归因到"太忙"显得敷衍。', '不要把责任推给"作业太多批不过来";不要承认"没顾上"这类失职表述;补批后主动同步。', 9),
('classroom-discipline', '课堂纪律/孩子被影响', '我家孩子说同桌老讲话，影响Ta听课，能不能换座位？', '{家长称呼}您好，{学生姓名}能主动反馈听课被打扰，说明Ta很在意学习，这点值得肯定。课堂干扰我会正面处理：先在课堂上关注并提醒，再视情况调整同桌搭配，同时引导孩子们互相约束。在调整到位前，我会留意{学生姓名}座位周边的情况，请您放心，也谢谢您及时沟通。', '肯定孩子反馈意愿，给出分层处置（提醒/调位/引导），不简单"换座位"了事。', '不要直接点名批评同桌;不要承诺立刻调走某同学;避免在家长间制造对立。', 10),
('teacher-coldness', '老师态度冷漠', '我家孩子说老师都不怎么理Ta，是不是不喜欢我家孩子？', '{家长称呼}您好，听到{学生姓名}有这种感受我挺意外的，也谢谢您告诉我，孩子的感受很重要。我在课堂上对每个孩子都一视同仁，可能近期对{学生姓名}的关注点没照顾到Ta的期待。我会增加和{学生姓名}的互动，比如多提问、多鼓励。也欢迎您观察几天后咱们再交流，看看{学生姓名}的感受有没有变化。', '不否认孩子的主观感受，把"冷漠"转化为"沟通方式需调整"，给出可观察的跟进动作。', '不要急于自我辩解"我没有偏心";不要承诺"以后天天表扬";避免把问题归到孩子"想太多"。', 11),
('child-isolated', '孩子被孤立', '我家孩子说同学都不跟Ta玩，是不是被排挤了？', '{家长称呼}您好，听到{学生姓名}说没人跟Ta玩，我立刻重视起来，孩子的同伴关系直接影响Ta的校园幸福感。我会先侧面观察{学生姓名}在课间和小组活动中的状态，了解是{具体行为}（如刚换小组/性格慢热/个别摩擦）哪种情况，再针对性引导。建议您也和{学生姓名}聊聊具体场景，咱们一起帮Ta建立交友的小方法。', '重视但不急于定性"校园排挤"，先客观观察归因，再给家长可配合的具体动作。', '不要轻易使用"校园霸凌""排挤"等定性词;不要在群里点名其他孩子;保护孩子隐私不在公开场合讨论。', 12),
('punishment-question', '罚站/体罚质疑', '听说老师让孩子罚站了，这不是体罚吗？', '{家长称呼}您好，您对"罚站"的关切我完全理解，孩子的身心健康是底线。我说明一下当时情况：{具体行为}（如让孩子站到队伍末尾调整状态/课间提醒），目的是规范行为而非惩罚身体，过程很短也没有伤害{学生姓名}。我会反思这种方式是否合适，今后更多用正向提醒代替。如果您方便，咱们当面沟通确认细节，避免误会。', '正视家长对体罚的敏感，澄清事实与目的，适度反思方式，坚守不体罚底线，避免硬碰硬。', '不要否认或淡化家长反映;不要承认"体罚"定性（承认即担责）;不与家长争论"这不算体罚";必要时请学校共同沟通。', 13),
('incomplete-homework-criticized', '作业没完成被批评', '我家孩子作业没写完就被批评了，至于这么严厉吗？', '{家长称呼}您好，理解您心疼孩子被批评。完成作业是培养{学生姓名}学习习惯的重要一环，我当时提醒的出发点是希望Ta重视，并不是要否定孩子。我会注意方式，以鼓励和提醒为主。也恳请您在家帮我一起关注{学生姓名}的作业完成，咱们家校配合，孩子进步会更快。', '共情家长护短心理，但坚守作业管理要求，把"批评"转化为"家校协同养成习惯"。', '不要全盘认错显得要求不严肃;不要把责任全推给家长"没盯作业";避免在群里公开讨论孩子作业未完成。', 14),
('ranking-pressure', '成绩排名压力', '学校还排名啊，我家孩子压力太大了，能不能不排？', '{家长称呼}您好，您对孩子心理压力的关心很到位。需要说明的是，按相关规定我们不会对外公开排名，{班级名称}内部的成绩反馈主要是帮助老师和孩子了解学情，不是制造竞争。我会注意反馈方式，对{学生姓名}更多关注进步和薄弱点，淡化名次。也建议咱们在家少提名次、多聊具体进步，给孩子减负。', '援引"不公开排名"政策回应，把关注点从"名次"引导到"学情诊断"，避免与家长对立。', '不要承认"我们在排名"（违反规定）;不要把成绩单/名次截图发给家长;不在群里发布任何排名信息。', 15),
('teacher-change', '老师换人不满', '怎么又换老师了，我家孩子刚适应，这不是折腾孩子吗？', '{家长称呼}您好，完全理解您和{学生姓名}对换老师的顾虑，孩子适应新老师确实需要时间。师资调整是学校综合安排，我作为{班级名称}的班主任会做好衔接：帮新老师快速了解每个孩子，也帮孩子们平稳过渡，{学生姓名}的情况我会特别交接。建议您给{学生姓名}一些正向引导，告诉Ta不同的老师会带来新的收获，咱们一起帮Ta适应。', '共情家长对"换老师"的不安，把不可控的调整转化为可控的衔接动作，避免抱怨学校安排。', '不要评价前任/新任老师好坏;不要抱怨学校"瞎安排";不在家长面前表态"我也不想换"。', 16),
('lost-belongings', '孩子丢东西', '我家孩子的文具/校服在学校丢了，你们得管管。', '{家长称呼}您好，孩子东西丢了确实让人着急，尤其{学生姓名}心爱的物品。我会在{班级名称}里帮着留意，也引导孩子们养成保管自己物品的习惯。建议您先和{学生姓名}回忆一下最后使用的场景，把物品特征告诉我，我帮Ta在班级失物处和同学间找一找。同时这也是教孩子保管物品的好契机，咱们一起引导。', '重视家长诉求，把"丢东西"转化为培养孩子保管习惯的教育契机，避免承诺"学校赔偿"。', '不要承诺学校/老师赔偿;不要在没有证据时怀疑某同学"偷拿";贵重物品建议在家不带来。', 17),
('late-dismissal', '放学太晚', '怎么放学这么晚，孩子到家都天黑了，安全谁负责？', '{家长称呼}您好，您对孩子放学时间和安全的关心我完全理解。放学时间由学校统一安排（含课后服务时段），目的是兼顾家长接送和{学生姓名}的拓展学习。如果课后服务您觉得不适合{学生姓名}，可以按流程申请不参加，按正常放学时间离校。关于路途安全，建议您和{学生姓名}约定固定的接送或回家路线，我也在班会上加强安全教育。', '把"放学晚"归因到统一安排和课后服务，给出可选方案（不参加），同时落实安全教育。', '不要把责任推给学校"规定如此"显得推诿;不要承诺"提前放";不评价课后服务收费合理性。', 18),
('tutorial-fee-question', '补课/收费质疑', '学校是不是在搞补课收费？这合规吗？', '{家长称呼}您好，您对收费合规性的关注很必要，这点咱们要说清楚。课后服务/相关活动都遵循自愿参加原则，收费标准由上级统一核定公示，不存在强制补课收费。如果您对{班级名称}某项费用的依据有疑问，我可以帮您查询对应的公示文件，或者您直接向学校财务/上级部门核实，确保每一项都明明白白。', '对收费质疑直接、清晰、合规回应，提供可核验的官方渠道，不回避不模糊。', '不要承诺"免费"或"取消收费";不要私下解释收费标准（应指向官方公示）;不在群里讨论费用细节引发集体争议。', 19),
('school-refusal', '孩子不想上学', '我家孩子说不想上学了，是不是在学校受委屈了？', '{家长称呼}您好，听到{学生姓名}说不想上学我立刻警觉起来，孩子的厌学信号咱们要高度重视。厌学原因往往比较复杂，可能是{具体行为}（课业压力/同伴关系/某个具体事件），需要家校一起排查。我会先侧面了解{学生姓名}近期在校的状态和人际，请您在家温和地陪Ta聊聊，不追问不施压。信息对齐后咱们再共同制定帮助方案，必要时联系学校心理老师介入。', '高度警觉但不急于归因"受委屈"，先家校信息对齐再制定方案，体现专业与谨慎。', '不要轻易下"校园霸凌""抑郁"等定性结论;不要把原因单方面归到学校或家庭;涉及心理问题建议转介专业资源。', 20)
