-- 通用话术库初始数据（20 个场景）
-- 幂等：使用 INSERT ... ON DUPLICATE KEY UPDATE，重复执行不会产生重复数据
-- 用法：npm run db:init 会自动在 schema.sql 后执行此文件

USE `jiaxiao`;

ON DUPLICATE KEY UPDATE
  `title` = VALUES(`title`),
  `parent_expression` = VALUES(`parent_expression`),
  `reply_template` = VALUES(`reply_template`),
  `strategy` = VALUES(`strategy`),
  `risk` = VALUES(`risk`),
  `sort_order` = VALUES(`sort_order`),
  `updated_at` = CURRENT_TIMESTAMP;
